package com.bananalab.lite;
import android.content.*;
import org.json.*;import java.util.*;import java.util.regex.*;
/** Java examples found in pages the user sent. They are text until the project's own compiler accepts them;
 *  nothing here is executed, and only an example that compiled can be offered to the code editor. */
final class CodeBank{
 static final int MAX=60,SNIPPET=4000,TOTAL=200000;
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-code-bank",0);}
 static JSONArray rows(Context c)throws Exception{return new JSONArray(prefs(c).getString("rows","[]"));}
 static void save(Context c,JSONArray rows)throws Exception{if(!prefs(c).edit().putString("rows",rows.toString()).commit())throw new java.io.IOException("No pude guardar los ejemplos de código");}
 static final Pattern TYPE=Pattern.compile("(?m)^\\s*(?:(?:public|final|abstract|static|strictfp)\\s+)*(class|interface|enum)\\s+([A-Z][A-Za-z0-9_]*)\\b[^;{]*\\{"),METHOD=Pattern.compile("(?m)^\\s*(?:(?:public|private|protected|static|final|synchronized)\\s+)*(?:void|int|long|double|float|boolean|char|byte|short|String|[A-Z][A-Za-z0-9_<>,\\[\\] ]*)\\s+[a-z][A-Za-z0-9_]*\\s*\\([^;{}]*\\)\\s*(?:throws [A-Za-z0-9_., ]+)?\\s*\\{");
 /** Conservative: Java-shaped text with balanced braces. Other languages and markup are left out. */
 static boolean looksJava(String code){String s=code.trim();if(s.length()<40||s.length()>SNIPPET||s.indexOf(';')<0||s.indexOf('{')<0)return false;if(s.startsWith("<")||s.contains("</")||s.contains("#include")||s.contains("function ")||s.contains("console.log")||s.contains("def ")||s.contains("fun ")||s.contains("=>")||s.contains(":=")||s.contains("using System")||s.contains("namespace ")||s.contains("std::")||s.contains("$ ")||s.contains("let ")||s.contains("var ")&&!s.contains("class "))return false;int depth=0;boolean text=false;char quote=0;for(int i=0;i<s.length();i++){char ch=s.charAt(i);if(text){if(ch=='\\')i++;else if(ch==quote)text=false;continue;}if(ch=='"'||ch=='\''){text=true;quote=ch;continue;}if(ch=='{')depth++;else if(ch=='}'&&--depth<0)return false;}if(depth!=0||text)return false;return TYPE.matcher(s).find()||METHOD.matcher(s).find()||s.matches("(?s).*\\b(?:System\\.out\\.print|new [A-Z][A-Za-z0-9_<>]*\\(|import java\\.).*");}
 static String kind(String code){return TYPE.matcher(code).find()?"clase":METHOD.matcher(code).find()?"metodos":"sentencias";}
 /** Adds the Java-looking blocks of a page. Returns how many were new. */
 static int add(Context c,List<String> blocks,String source)throws Exception{if(blocks==null||blocks.isEmpty())return 0;JSONArray rows=rows(c);Set<String> known=new HashSet<>();for(int i=0;i<rows.length();i++)known.add(rows.getJSONObject(i).getString("id"));int added=0;for(String block:blocks){String code=block.replace("\r\n","\n").replace('\r','\n').replace('\u00a0',' ').trim();if(!looksJava(code))continue;String id=JavaMethodEditor.hash(code);if(!known.add(id))continue;if(rows.length()>=MAX||rows.toString().length()+code.length()>TOTAL)break;rows.put(new JSONObject().put("id",id).put("code",code).put("source",source).put("kind",kind(code)).put("status","sin comprobar").put("detail","").put("saved",System.currentTimeMillis()));added++;}if(added>0)save(c,rows);return added;}
 /** File name and compilable source inside Banana's package for an example, or an explanation in [1] when it cannot be placed. */
 static String[] candidate(Set<String> existing,JSONObject row,int number)throws Exception{String code=row.getString("code"),kind=row.getString("kind");StringBuilder imports=new StringBuilder();Matcher imp=Pattern.compile("(?m)^\\s*import\\s+(?:static\\s+)?[A-Za-z0-9_.*]+\\s*;\\s*$").matcher(code);while(imp.find())imports.append(imp.group().trim()).append('\n');String body=imp.reset().replaceAll("").replaceAll("(?m)^\\s*package\\s+[A-Za-z0-9_.]+\\s*;\\s*$","").trim();
  if(kind.equals("clase")){Matcher type=TYPE.matcher(body);if(!type.find())return new String[]{null,"No encontré la declaración de la clase."};String name=type.group(2);for(String file:existing)if(file.equalsIgnoreCase(name+".java"))return new String[]{null,"Ya existe "+file+" en Banana; no reemplazo una clase propia con un ejemplo leído."};return new String[]{name+".java","package com.bananalab.lite;\n"+imports+body+"\n"};}
  String name="EjemploLeido"+number;for(String file:existing)if(file.equalsIgnoreCase(name+".java"))return new String[]{null,"Ya existe "+file+"; deshacé o renombrá ese ejemplo antes."};
  return new String[]{name+".java","package com.bananalab.lite;\n"+imports+"final class "+name+"{\n"+(kind.equals("metodos")?body:" static void ejemplo()throws Exception{\n"+body+"\n }")+"\n}\n"};}
 static JSONObject pick(JSONArray rows,int number){if(number<1||number>rows.length())throw new IllegalArgumentException("No tengo un ejemplo "+number+". Hay "+rows.length()+".");return rows.optJSONObject(number-1);}
 static String list(Context c)throws Exception{JSONArray rows=rows(c);if(rows.length()==0)return "Todavía no guardé ejemplos de Java. Pasame una página que tenga bloques de código Java y los separo de su texto.";int ok=0,bad=0;for(int i=0;i<rows.length();i++){String s=rows.getJSONObject(i).getString("status");if(s.equals("compila"))ok++;else if(s.equals("no compila"))bad++;}StringBuilder out=new StringBuilder("Ejemplos de Java leídos: "+rows.length()+" · compilan dentro de Banana: "+ok+" · no compilan: "+bad+" · sin comprobar: "+(rows.length()-ok-bad)+"\n");for(int i=Math.max(0,rows.length()-12);i<rows.length();i++){JSONObject r=rows.getJSONObject(i);String first=r.getString("code").split("\n")[0].trim();out.append("\n").append(i+1).append(". [").append(r.getString("kind")).append(" · ").append(r.getString("status")).append("] ").append(first.length()>70?first.substring(0,70)+"…":first);}return out.append("\n\nDecí «mostrame el ejemplo 3», «probá el ejemplo 3» para compilarlo sin incorporarlo, o «usá el ejemplo 3» si ya compiló. Son textos de las páginas: no los ejecuté ni verifiqué qué hacen.").toString();}
 static String show(Context c,int number)throws Exception{JSONObject r=pick(rows(c),number);return "Ejemplo "+number+" ("+r.getString("kind")+" · "+r.getString("status")+")\nFuente: "+r.getString("source")+"\n\n"+r.getString("code")+(r.getString("detail").isEmpty()?"":"\n\nÚltima comprobación: "+r.getString("detail"));}
 /** Compiles the example together with the whole project, without staging it. The compiler's verdict is stored with the example. */
 static String verify(Context c,int number)throws Exception{JSONArray rows=rows(c);JSONObject r=pick(rows,number);NaturalCoding.project(c);JSONObject working=JavaProject.working(c);String[] file=candidate(JavaProject.files(c,working).keySet(),r,number);String status,detail;if(file[0]==null){status="no compila";detail=file[1];}else{JSONObject changes=new JSONObject(working.toString()).put(file[0],file[1]);String report=JavaProject.compile(c,changes,false);boolean ok=report.startsWith("Compilación completa aprobada");status=ok?"compila":"no compila";detail=ok?"Compila junto con todo Banana como "+file[0]+".":report.substring(0,Math.min(600,report.length()));}
  rows=rows(c);for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).getString("id").equals(r.getString("id")))rows.getJSONObject(i).put("status",status).put("detail",detail);save(c,rows);return "Ejemplo "+number+": "+status+".\n"+detail+(status.equals("compila")?"\nNo lo incorporé ni lo ejecuté. Si lo querés en la copia de fuentes, decí «usá el ejemplo "+number+"».":"\nQuedó guardado como texto con el resultado del compilador.");}
 /** Hands a compiled example to the existing general editor, which compiles again, stages it and can undo it. */
 static String use(Context c,int number)throws Exception{JSONObject r=pick(rows(c),number);if(!r.getString("status").equals("compila"))return "Primero tiene que compilar: decí «probá el ejemplo "+number+"». Estado actual: "+r.getString("status")+".";NaturalCoding.project(c);String[] file=candidate(JavaProject.files(c,JavaProject.working(c)).keySet(),r,number);if(file[0]==null)return file[1];GeneralEditPlan plan=GeneralEditPlan.parse("crea "+file[0]+" con:\n```java\n"+file[1].trim()+"\n```");if(plan==null)return "El editor general no aceptó el ejemplo con su formato actual.";return GeneralSourceChat.apply(c,plan)+"\nOrigen del código: "+r.getString("source")+". Es código de una página; compilar no prueba su comportamiento.";}
 static String clear(Context c)throws Exception{save(c,new JSONArray());return "Borré los ejemplos de Java leídos. Las ediciones ya preparadas en la copia de fuentes no cambian.";}
 /** Chat intents: null when the message is about something else. */
 static String[] parse(String raw){String q=ChatLanguage.normalize(NaturalCoding.polite(raw));if(q.matches("(?:que )?ejemplos de (?:java|codigo)(?: aprendiste| leiste| guardaste| tenes)?|(?:mostrame|lista|ver) (?:los |tus )?ejemplos de (?:java|codigo)|que codigo (?:aprendiste|leiste)"))return new String[]{"list",""};Matcher m=Pattern.compile("(mostrame|muestra|ver|proba|prueba|compila|verifica|usa|incorpora|aplica) el ejemplo(?: de (?:java|codigo))?(?: numero)? ([0-9]{1,3})").matcher(q);if(m.matches()){String verb=m.group(1);return new String[]{verb.matches("mostrame|muestra|ver")?"show":verb.matches("usa|incorpora|aplica")?"use":"verify",m.group(2)};}if(q.matches("(?:borra|olvida) (?:los |tus )?ejemplos de (?:java|codigo)"))return new String[]{"clear",""};return null;}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String[] p=parse(input);if(p==null)return null;JavaChat.owner=Thread.currentThread();try{String text;int n=p[1].isEmpty()?0:Integer.parseInt(p[1]);if(p[0].equals("list"))text=list(c);else if(p[0].equals("show"))text=show(c,n);else if(p[0].equals("clear"))text=clear(c);else if(p[0].equals("verify")){JavaChat.phase("Compilando el ejemplo junto con todo Banana, sin incorporarlo…");text=verify(c,n);}else{JavaChat.phase("Preparando el ejemplo en la copia de fuentes…");text=use(c,n);}return MobileCore.say(c,text,"app_ajuste");}catch(Exception e){return MobileCore.say(c,"No pude con ese ejemplo: "+AndroidRepair.summary(e),"app_ajuste");}finally{JavaChat.owner=null;JavaChat.progress="";}}
}
